def mc2_p2(doc):
    choices = doc["mc2_targets"]["choices"]
    formatted_choices = "".join(list(map(lambda choice: f"
- {choice}", choices)))
    return f"Pregunta: {doc['question']}
Escolle a resposta correcta da lista:
{formatted_choices}
Cal é a resposta correcta?
Respuesta:"

